/* Source: shared/lib/orders.js; kraneHandle_orders_quantity. Generated by standalone-build.mjs. */
function kraneHandle_orders_quantity(e, qbtn) {
      const ctl = qbtn.closest('[data-qty]');
      const nEl = ctl.querySelector('[data-qty-n]');
      const min = parseInt(ctl.dataset.min || '1', 10);
      const max = parseInt(ctl.dataset.max, 10), unit = parseInt(ctl.dataset.unit, 10);
      let q = parseInt(nEl.textContent, 10);
      q = qbtn.hasAttribute('data-qty-minus') ? Math.max(min, q - 1) : Math.min(max, q + 1);
      const item=ctl.closest('[data-order-item]')?.dataset.orderItem;
      const nextQuantities=Object.assign({},flowState.orderState.quantities,item ? {[item]:q} : {});
      nEl.textContent = q;
      ctl.querySelector('[data-qty-minus]').disabled = q <= min;
      ctl.querySelector('[data-qty-plus]').disabled = q >= max;
      const row=ctl.closest('[data-order-item]');
      const line = row?.querySelector('[data-line-price],[data-order-price]');
      if(line) line.textContent = '฿ ' + (unit * q).toLocaleString();
      if(item){
        flowState.orderState.quantities[item]=q;
        invalidateFulfillmentQuote();
        persistFlowState();
        syncOrderCheckout();
        syncDeclinedMedicines();
        refreshMedicationCheckout();
      }
      return true;

  return false;
}

/* Source: shared/lib/ui.js; syncDeclinedMedicines. Generated by standalone-build.mjs. */
function syncDeclinedMedicines(){
    const plan=document.getElementById('plan');
    if(!plan) return;
    const wrap=plan.querySelector('[data-declined-list]');
    const target=plan.querySelector('[data-declined-items]');
    if(!wrap || !target) return;
    const declined=[];
    plan.querySelectorAll('[data-order-item]').forEach(row => {
      const key=row.dataset.orderItem;
      const ctl=row.querySelector('[data-qty]');
      if(!ctl) return;
      const q=parseInt(ctl.querySelector('[data-qty-n]')?.textContent || '0',10);
      const nameEl=row.querySelector('[style*="fw-semibold"]');
      const name=(nameEl?.textContent || key).trim();
      row.hidden = q<=0;
      if(q<=0) declined.push({key,name});
    });
    target.innerHTML = declined.map(d =>
      '<div class="declined-row"><span class="grow">'+d.name+'</span>'+
      '<button type="button" class="btn btn--ghost btn--sm" data-restore-item="'+d.key+'">เพิ่มกลับ</button></div>'
    ).join('');
    wrap.hidden = declined.length===0;
  }
